/* AIVIC_FUNCTION_BUNDLE_START owner=calculateFoodRatingPriority exports=calculateFoodRatingPriority */
const __aivicBundle_3_calculateFoodRatingPriority = (() => {
  function calculateFoodRatingPriority(input: {
    dish_id: string;
    dish_name: string;
    rating_data: Array<{
      dish_id: string;
      dish_name: string;
      family_member_id: string;
      satisfaction_score: number;
      evaluation_datetime: Date;
    }>;
  }): {
    priority_score: number;
    total_evaluations: number;
    high_rating_count: number;
    low_rating_count: number;
  } {
    const { rating_data } = input;
  
    if (!rating_data || rating_data.length === 0) {
      throw new Error('評価データが存在しません');
    }
  
    const total_evaluations = rating_data.length;
    let high_rating_count = 0;
    let low_rating_count = 0;
    let sum = 0;
  
    for (const rating of rating_data) {
      const score = rating.satisfaction_score;
      sum += score;
  
      if (score >= 4) {
        high_rating_count++;
      } else if (score <= 2) {
        low_rating_count++;
      }
    }
  
    const priority_score = sum / total_evaluations;
  
    return {
      priority_score,
      total_evaluations,
      high_rating_count,
      low_rating_count,
    };
  }
  return { calculateFoodRatingPriority };
})();
