const __aivicBundle_21_aggregateMonthlyCostWithNoRecords = (() => {
  async function aggregateMonthlyCostWithNoRecords(input: {
    userId: string;
    targetYear: number;
    targetMonth: number;
  }): Promise<{
    userId: string;
    year: number;
    month: number;
    totalAmount: number;
    purchaseCount: number;
    categoryBreakdown: Array<any>;
    averagePricePerItem: number;
  }> {
    const { userId, targetYear, targetMonth } = input;
  
    // API: 購入記録取得エンドポイント
    const purchaseRecordsResponse = await fetch(
      `/api/purchase-records?userId=${userId}&year=${targetYear}&month=${targetMonth}`,
      { method: 'GET' }
    );
    const purchaseRecordsData = await purchaseRecordsResponse.json();
  
    // API: 月次集計結果取得エンドポイント
    const aggregationResponse = await fetch(
      `/api/monthly-cost-aggregation?userId=${userId}&year=${targetYear}&month=${targetMonth}`,
      { method: 'GET' }
    );
    const aggregationData = await aggregationResponse.json();
  
    // 購入記録が空配列の場合、全フィールドを0/空で返す
    if (
      purchaseRecordsData.purchaseRecords &&
      purchaseRecordsData.purchaseRecords.length === 0
    ) {
      return {
        userId,
        year: targetYear,
        month: targetMonth,
        totalAmount: 0,
        purchaseCount: 0,
        categoryBreakdown: [],
        averagePricePerItem: 0,
      };
    }
  
    // 集計データを返す
    return {
      userId: aggregationData.userId,
      year: aggregationData.year,
      month: aggregationData.month,
      totalAmount: aggregationData.totalAmount,
      purchaseCount: aggregationData.purchaseCount,
      categoryBreakdown: aggregationData.categoryBreakdown,
      averagePricePerItem: aggregationData.averagePricePerItem,
    };
  }
  return { aggregateMonthlyCostWithNoRecords };
})();
